using namespace std;using L=long;struct T{L A,B,C;T(L x=0,L y=0):A(x),B(y),C(0){}L M(T P,L S){L v=P.B;if(P.A==1){C+=v*S;if(!A)A=1,B=v;else if(A==1)A=1,B+=v;else B+=v;}else if(P.A==2)C=v*S,A=2,B=v;}}y;vector<L>v;vector<T>Y;L n,a,b;L z(L i,L l,L r){L m=(l+r)/2;return Y[i].C=l+1==r?v[l-1]:z(2*i,l,m)+z(2*i+1,m,r);}L Z(L i,L a,L b,L l,L r,T&U){T&n=Y[i];L m=(l+r)/2,R=2*i,S=R+1;if(a==l&&b==r)n.M(U,r-l),U.C+=n.C;else{Y[R].M(n,m-l);Y[S].M(n,r-m);n.A=n.B=0;if(b<=m)Z(R,a,b,l,m,U);else if(a>=m)Z(S,a,b,m,r,U);else Z(R,a,m,l,m,U),Z(S,m,b,m,r,U);n.C=Y[R].C+Y[S].C;}}main(){cin>>n>>a;Y.resize(4*n);for(a=0;a<n;a++)cin>>b,v.push_back(b);z(1,1,n+1);while(cin>>y.A)if(y.A<3)cin>>a>>b>>y.B,Z(1,a,b+1,1,n+1,y);else y.A=0,y.C=0,cin>>a>>b,Z(1,a,b+1,1,n+1,y),cout<<y.C<<endl;}
